'use strict';
const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
function outputs(rows) {
    if (!Array.isArray(rows) || rows.some(row => !row.match || !['works', 'order', 'clash'].includes(row.level) || typeof row.note !== 'string')) throw new Error('Invalid plugin compatibility table.');
    const cell = value => String(value || '').replace(/\|/g, '\\|').replace(/[\r\n]/g, ' ');
    return {
        'src/11_plugin_clash_table.js': '// @editor-only\n// Generated by npm run clashes from data/DocsDoodadsPluginCompatibility.json.\nDocsDoodads.PluginClashTable = ' + JSON.stringify(rows, null, 4) + ';\n',
        'docs/PLUGIN_COMPATIBILITY.md': '# Plugin order and compatibility findings\n\nGenerated from `data/DocsDoodadsPluginCompatibility.json` by `npm run clashes`. Order advisories do not establish tested compatibility. The third-party playtests for backlog 7.4.5 remain pending.\n\n| Plugin | Finding | Note |\n| --- | --- | --- |\n' + rows.map(row => '| ' + cell(row.match) + ' | ' + cell(row.level) + ' | ' + cell(row.note) + ' |').join('\n') + '\n'
    };
}
if (require.main === module) {
    const files = outputs(JSON.parse(fs.readFileSync(path.join(root, 'data/DocsDoodadsPluginCompatibility.json'), 'utf8')));
    for (const [file, text] of Object.entries(files)) {
        const target = path.join(root, file);
        if (process.argv.includes('--check')) {
            if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== text) { console.error(file + ' is stale; run npm run clashes.'); process.exitCode = 1; }
        } else fs.writeFileSync(target, text);
    }
    if (!process.exitCode) console.log('Plugin table and compatibility notes are current.');
}
module.exports = { outputs };
